import rclpy
from rclpy.node import Node
from bodyctrl_msgs.msg import MotorStatusMsg, CmdMotorCtrl, CmdSetMotorPosition
import matplotlib.pyplot as plt
from collections import deque

class PositionPlotNode(Node):
    def __init__(self):
        super().__init__('plot_pos_node')
        
        # 声明ROS2参数
        self.declare_parameter('maxlen', 1000)
        self.declare_parameter('id', 11)
        
        # 从参数中读取值
        self.maxlen = self.get_parameter('maxlen').get_parameter_value().integer_value
        self.motor_id = self.get_parameter('id').get_parameter_value().integer_value
        
        self.get_logger().info(f'参数设置: maxlen={self.maxlen}, motor_id={self.motor_id}')
        
        # Save historical position data
        self.positions = deque(maxlen=self.maxlen)
        self.cmd_positions = deque(maxlen=self.maxlen)  # 存储命令位置值
        self.time_stamps = deque(maxlen=self.maxlen)
        
        # 保存最新的命令位置值
        self.latest_cmd_position = 0.0

        self.sub_status = self.create_subscription(
            MotorStatusMsg,
            '/arm/status',
            self.status_callback,
            10
        )
        # 订阅 /arm/cmd_ctrl 话题（CmdMotorCtrl 消息，包含 pos 字段）
        self.sub_cmd_ctrl = self.create_subscription(
            CmdMotorCtrl,
            '/arm/cmd_ctrl',
            self.cmd_ctrl_callback,
            10
        )
        # 订阅 /arm/cmd_pos 话题（CmdSetMotorPosition 消息，包含 cmds 列表，每个元素有 pos 字段）
        self.sub_cmd_pos = self.create_subscription(
            CmdSetMotorPosition,
            '/arm/cmd_pos',
            self.cmd_pos_callback,
            10
        )

        # For live plotting
        plt.ion()
        self.fig, self.ax = plt.subplots()
        self.position_line, = self.ax.plot([], [], label=f"Actual Position (Motor {self.motor_id})", color='blue')
        self.cmd_position_line, = self.ax.plot([], [], label=f"Cmd Position (Motor {self.motor_id})", color='red')
        self.ax.set_xlabel('Sample Index')
        self.ax.set_ylabel('Position (rad)')
        self.ax.legend()
        self.ax.grid(True)
        self.fig.canvas.manager.set_window_title(f'Arm Monitor - Motor {self.motor_id} (Position Comparison)')
        self.counter = 0
        
        # 创建定时器，以固定频率更新绘图（30Hz）
        self.plot_timer = self.create_timer(1.0 / 30.0, self.update_plot)

    def status_callback(self, msg):
        # MotorStatusMsg 有 status 字段，是一个列表
        # 每个元素有 name, pos, speed, current, temperature 等字段
        position_val = 0.0
        for motor in msg.status:
            if motor.name == self.motor_id:
                position_val = motor.pos
                break
        
        self.positions.append(position_val)
        self.time_stamps.append(self.counter)
        self.counter += 1
        
        # 使用最新的命令位置值添加到队列
        # 这样确保每个状态点都对应最新的命令值
        self.cmd_positions.append(self.latest_cmd_position)

    def cmd_ctrl_callback(self, msg):
        # CmdMotorCtrl 有 cmds 字段，是一个列表
        # 每个元素有 name, pos, spd, tor, kp, kd 等字段
        cmd_position_val = 0.0
        for cmd in msg.cmds:
            if cmd.name == self.motor_id:
                cmd_position_val = cmd.pos
                break
        
        # 更新最新的命令位置值
        # 这个值会在 status_callback 中被使用
        self.latest_cmd_position = cmd_position_val

    def cmd_pos_callback(self, msg):
        # CmdSetMotorPosition 有 cmds 字段，是一个列表
        # 每个元素有 name, pos, spd, cur 等字段
        cmd_position_val = 0.0
        for cmd in msg.cmds:
            if cmd.name == self.motor_id:
                cmd_position_val = cmd.pos
                break
        
        # 更新最新的命令位置值
        # 这个值会在 status_callback 中被使用
        self.latest_cmd_position = cmd_position_val

    def update_plot(self):
        # Synchronize lengths - 确保所有数据长度一致
        min_len = min(len(self.time_stamps), len(self.positions), len(self.cmd_positions))
        if min_len == 0:
            return
        
        x = list(self.time_stamps)[-min_len:]
        y1 = list(self.positions)[-min_len:]
        y2 = list(self.cmd_positions)[-min_len:]
        
        self.position_line.set_data(x, y1)
        self.cmd_position_line.set_data(x, y2)
        
        # 更新坐标轴范围
        self.ax.relim()
        self.ax.autoscale_view()
        
        # 刷新绘图
        self.fig.canvas.draw()
        self.fig.canvas.flush_events()

def main(args=None):
    rclpy.init(args=args)
    node = PositionPlotNode()
    try:
        rclpy.spin(node)
    except KeyboardInterrupt:
        pass
    finally:
        node.destroy_node()
        rclpy.shutdown()
        plt.ioff()
        plt.show()

if __name__ == '__main__':
    main()
